contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint value) public payable {
        bool setReverted;
        c.SetMinSum(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            setReverted = true;
        } else {
            setReverted = false;
        }

        uint observedMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(setReverted || observedMinSum == value);
    }

    receive() external payable {}
}

