// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 value) internal {
        bool setReverted;
        try c.SetMinSum(value) {
            setReverted = false;
        } catch {
            setReverted = true;
        }
        uint256 observedMinSum;
        try c.MinSum() returns (uint256 __r) { observedMinSum = __r; } catch { return; }
        assertTrue(setReverted || observedMinSum == value);
    }

    function testFuzz_run(uint256 value) public {
        _run(value);
    }

    receive() external payable {}
}
